package com.kiraworld.sarahtravel;
import android.content.Context;import android.util.Base64;import org.json.JSONArray;import org.json.JSONObject;import java.io.File;import java.io.FileOutputStream;
public final class SarahSyncImporter {private SarahSyncImporter(){}
    public static int importPayload(Context context,JSONObject payload)throws Exception{if(!"sarah-sync-v1".equals(payload.optString("schema")))throw new IllegalArgumentException("Unsupported Sarah sync schema");SarahDatabase db=new SarahDatabase(context);SyncSeenStore seen=new SyncSeenStore(context);int count=0;try{JSONArray messages=payload.optJSONArray("messages");if(messages!=null)for(int i=0;i<messages.length();i++){JSONObject r=messages.optJSONObject(i);if(r==null||!seen.first(r.optString("event_id",r.optString("id"))))continue;db.addMessage(r.optString("role","user"),r.optString("content",""));count++;}JSONArray memories=payload.optJSONArray("memories");if(memories!=null)for(int i=0;i<memories.length();i++){JSONObject r=memories.optJSONObject(i);if(r==null)continue;String id=r.optString("memory_id",r.optString("category")+"|"+r.optString("summary"));if(!seen.first(id))continue;db.addMemory(r.optString("category","memory"),r.optString("summary",""),r.optString("source","trusted sync"));count++;}JSONArray trips=payload.optJSONArray("trips");if(trips!=null)for(int i=0;i<trips.length();i++){JSONObject r=trips.optJSONObject(i);if(r==null)continue;String id=r.optString("trip_id",r.optString("title")+"|"+r.optString("destination"));if(!seen.first(id))continue;db.addTrip(r.optString("title","Trip"),r.optString("destination",""),r.optString("status","planned"),r.optString("notes",""));count++;}JSONArray wishes=payload.optJSONArray("wishes");if(wishes!=null)for(int i=0;i<wishes.length();i++){JSONObject r=wishes.optJSONObject(i);if(r==null)continue;String id=r.optString("wish_id",r.optString("destination"));if(!seen.first(id))continue;db.addWish(r.optString("destination",""),r.optString("notes",""));count++;}JSONArray mind=payload.optJSONArray("mind_events");if(mind!=null)for(int i=0;i<mind.length();i++){JSONObject r=mind.optJSONObject(i);if(r==null||!seen.first(r.optString("event_id")))continue;MindEventStore.recordLocal(context,db.getProfile().getOrDefault("name","Traveler"),r.optString("spoken",""),r.optString("private_mind",""),r.optString("factual_truth",""),r.optString("classification","UNCERTAIN_BELIEF"));count++;}JSONArray discoveries=payload.optJSONArray("discoveries");if(discoveries!=null){ProactiveDiscoveryStore store=new ProactiveDiscoveryStore(context);try{String speaker=db.getProfile().getOrDefault("name","Traveler");for(int i=0;i<discoveries.length();i++){JSONObject r=discoveries.optJSONObject(i);if(r==null)continue;String id=r.optString("discovery_id",r.optString("url"));if(!seen.first(id))continue;TavilyClient.Result result=new TavilyClient.Result(r.optString("title","Possible travel match"),r.optString("url",""),r.optString("summary",""));if(store.add(speaker,result,r.optString("query_text",r.optString("query","trusted sync")),r.optString("category","synced")))count++;}}finally{store.close();}}JSONArray photos=payload.optJSONArray("photos");if(photos!=null)for(int i=0;i<photos.length();i++){JSONObject r=photos.optJSONObject(i);if(r==null||!seen.first(r.optString("photo_id",r.optString("sha256"))))continue;byte[] bytes=Base64.decode(r.optString("jpeg_base64",""),Base64.DEFAULT);if(bytes.length==0||bytes.length>4000000)continue;File dir=new File(context.getFilesDir(),"photos");dir.mkdirs();File file=new File(dir,r.optString("sha256",String.valueOf(System.nanoTime()))+".jpg");try(FileOutputStream out=new FileOutputStream(file)){out.write(bytes);}db.addPhoto(file.getAbsolutePath(),r.optString("caption","Synced trip photo"));count++;}return count;}finally{seen.close();db.close();}}
}
